from typing import List

def is_stack_terminable(stack: List[int], arr: List[int]) -> bool:
    top = -1
    for i in arr:
        if top == -1 or i != stack[top]:
            stack.append(i)
            top += 1
        else:
            stack.pop()
    return len(stack) == 0

def count_stack_terminable_subarrays(n: int, arr: List[int]) -> int:
    count = 0
    for i in range(n):
        for j in range(i, n):
            if is_stack_terminable([], arr[i:j+1]):
                count += 1
    return count

