from heapq import heappush, heappop

def find_max_quests(n, m, towers, quests):
    max_quests = 0
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    coordinates = [sum(coord) // 2 for coord in quests]
    locations = {sum(coord) % 2: (coord, turn) for coord, turn in zip(towers, range(len(towers)))}
    for turn, coord in enumerate(quests):
        next_turn = find_next_locs(locations, coord, turn)
        queued_locations = {(x, y): turn for x, y, turn in next_turn}
        tasks = deque()
        for loc in queued_locations:
            tasks.extend([(c[1], loc) for c in coordinates if c[0] == loc[0] and c[1] == loc[1]])
        while tasks:
            max_quests = max(max_quests, len(tasks))
            next_q_loc, turn_num = tasks.popleft()
            tasks.clear()
            neighbors = list(loc for loc in locations.keys() if next_q_loc[0] == loc[0] and next_q_loc[1] == loc[1])
            for next_loc in neighbors:
                if queued_locations[next_loc] == turn_num + 1:
                    heappush(tasks, (turn_num + 1, next_loc))
                    queued_locations[next_loc] = turn_num + 1
            next_locs = [locations[next_loc] for next_loc in neighbors if next_loc not in queued_locations]
            for loc in next_locs:
                if loc[0] == next_q_loc[0] and loc[1] == next_q_loc[1]:
                    continue
                queens = [(c[1], loc) for c in coordinates if c[0] == loc[0] and c[1] == loc[1] and c[2] == turn_num]
                for c in queens:
                    if c not in queued_locations:
                        heappush(tasks, (c[2], c))
                        queued_locations[c] = turn_num
    return max_quests

def find_next_locs(locations, loc, turn):
    result = []
    x, y = loc
    for dx, dy in directions:
        next_x = x + dx
        next_y = y + dy
        if next_x not in locations:
            continue
        next_loc = locations[next_x]
        if next_loc[0] == next_x and next_loc[1] == next_y and locations[next_loc][2] == 0:
            result.append((next_x + dx, next_y + dy, turn + 1))
    return result

