def tricky_permutations(a, b, c):
    if b > 0:
        yield from tricky_permutations(a, b-1, c)  # swap 'b' with 'a'
        yield from tricky_permutations(a, b-1, c)
    if a > 0 and b > 0:
        yield from tricky_permutations(a-1, b, c)  # swap 'a' with 'c'
        yield from tricky_permutations(a-1, b, c)

