from collections import defaultdict

def maximize_games(n, k, fans):
    rounds = [set(range(1, 2**n // 2 + 1)) for _ in range(n)]
    for i in range(1, n):
        rounds[i].symmetric_difference_update(rounds[i-1])  # No game winner has to advance to next round
        rounds[i].difference_update(rounds[i-1])  # dieretnd the loser
    for i in range(n-1):
        rounds[i+1] = rounds[i][::-1]  # ث- inverse for the esponent 2 , otherwise ke to dual
    for fan in fans:
        if fan in rounds[0]:
            continue
        rounds[1].add(fan)  # add fan result to upper bracket
    ans = 0
    for round in rounds:
        if not round:
            continue
        ans += 2**len(round) - 1
    ans += 2
    return ans

