import sys

def calculate_max_folds(sequence):
    if len(sequence) == 1:
        return [0]

    folding_sequence = [1]  # Start by assuming all elements fold together initially.
    longest_fold_length = 1  # Start with the minimum possible fold length.

    for i in range(1, len(sequence)):
        left_fold = -1
        right_fold = -1

        for j in range(i - 1, -1, -1):
            if folding_sequence[j] == 1 and largest_fold_extended(sequence, sequence[j + 1:i + 1]) < longest_fold_length:
                left_fold = j
                break

        for k in range(i, j + 1 - longest_fold_length, -1):
            if folding_sequence[k] == 1 and largest_fold_extended(sequence, sequence[k - i:j + 1]) < longest_fold_length:
                right_fold = k
                break

        if left_fold == -1 and right_fold == -1:
            folding_sequence.append(1)
            longest_fold_length += 1
        else:
            folding_sequence.append(-1)
            longest_fold_length = 1 if left_fold != -1 and right_fold != -1 and left_fold == right_fold else min(right_fold - left_fold + longest_fold_length, left_fold + k - right_fold + longest_fold_length - 2)

    return folding_sequence[:-1]

def largest_fold_extended(sequence, subsequence):
    if len(subsequence) < 2:
        return 0
    fold_length = 1
    left = right = 0

    while left < len(subsequence) and right < len(subsequence):
        while left < len(subsequence) and left < right + longest_fold_length + fold_length - 1 and subsequence[left] == fold_length * sequence[right]:
            left += 1
        while right < len(subsequence) - 1 >= 0 and right < left + 1 and sequence[right] == fold_length * sequence[right + 1]:
            right += 1
        fold_length += 1

    return fold_length - 1

