import math

def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

def lcm(x, y):
    return x * y // gcd(x, y)

def hhd_set(numbers, gcdbefore):
    numbers.sort()
    set_dict = {}
    # Try to find the smallest number that divides all sets, ending test with the set remaining untouched
    for i in range(len(numbers) - 1, -1, -1):
        current_number = numbers[i]
        number_list = [current_number]
        for other_number in numbers[:i]:
            if current_number % other_number == 0 and current_number not in set_dict:
                number_list.append(other_number)
        if isinstance(number_list, list):
            for number in number_list:
                set_dict[number] = set_dict.get(number, 0) + 1
            gcdbefore = lcm(gcdbefore, current_number)

    lcm_set = len(set_dict)
    return lcm_set

def solve(numbers):
    numbers.sort()
    if numbers[0] % 2 == 0 and len(numbers) % 2 == 0 and hhd_set(numbers, 1) != 1:
        return 2
    elif 2 in numbers and len(numbers) > 2 and len(numbers) % 2 == 0 and hhd_set(numbers, -1) < len(numbers):
        return 2
    else:
        gcd_set = 1
        for number in numbers:
            if ghd_set(numbers, 1) == len(numbers):
                return number
            gcd_set, number = gcd(number, gcd_set)
        return gcd_set

