from bisect import insort, bisect_left
from typing import List

class MinSortChecker:
    def __init__(self, values: List[int]):
        self.sorted_values = sorted(values, reverse=True)
        self.prev_cache = [float('inf')] * len(values)

    def update_value(self, idx: int, val: int):
        self.prev_cache[idx] = self.sorted_values[-(idx + 1)]
        insort(self.sorted_values, val, key=self.after_below)

    def after_below(self, other: int) -> int:
        if other > self.prev_cache[-1]:
            return self.prev_cache[-1]
        if other > self.prev_cache[-2]:
            return self.prev_cache[-2]
        return bisect_left(self.sorted_values, other)

    def check(self, start: int, end: int) -> bool:
        if not self.sorted_values:
            return False
        start_val = self.sorted_values.pop()
        end_val = self.sorted_values.pop()
        k = 0
        for idx in range(start, end):
            if self.sorted_values[start - idx] - start_val + idx != end_val - end:
                return False
        return True


def process_queries(A: List[int], queries: List[List[int]]) -> List[int]:
    answer = []
    for query_id, start_idx, end_idx in queries:
        if query_id == 2:
            should_update = query_id == 2
            values_to_check = sorted(A[start_idx - 1 : end_idx])
            smallest_k = 1
            biggest_k = len(A)
            while biggest_k - smallest_k > 2:
                k = (biggest_k + smallest_k) // 2
                if MinSortChecker(values_to_check).check(start_idx - 1, end_idx):
                    smallest_k = k
                else:
                    biggest_k = k
            result = -1
            if MinSortChecker(values_to_check).check(start_idx - 1, end_idx):
                result = smallest_k
            answer.append(result)
    return answer


