from collections import Counter

def is_balanced(s):
    return abs(s.count('a') - s.count('b')) <= 1 and abs(s.count('a') - s.count('c')) <= 1 and abs(s.count('b') - s.count('c')) <= 1

def mirror(s):
    return ''.join(['a' if x == 'b' else ('b' if x == 'c' else 'c') for x in s])

def count_balance_operations(s, mod=51123987):
    count = Counter()
    mirror_s = mirror(s)
    for i in range(len(s)):
        new_s = mirror(s)
        if not is_balanced(new_s):
            continue
        count[new_s] += 1
        new_s = mirror(mirror_s)
        if is_balanced(new_s):
            count[new_s] += 1
    return pow(51123987 - len(s.reduce('')), len(s), mod) * len(s.reduce('')) % mod

