def process_tiles(graph, n, m):
    queue = deque([[0, 0]])

    while queue:
        x, y = queue.popleft()

        temp = [y % 2, x % 2]

        # flip vertically
        if x // 2 == 1 and y % 2 == 0:
            temp[1] = 1 - temp[1]

        for i in range(4):
            new_x = (x * 2 + temp[i]) % n
            new_y = (y * 2 + temp[i + 1]) % m
