from heapq import heapify, heappop, heappush
from typing import List

def sort_suffixes(arr: List[int]) -> int:
    heap = []
    for i in range(len(arr)):
        if i <= len(arr) // 2:
            heappush(heap, arr[i])
        else:
            heappush(heap, arr[len(arr) - i])
    non_decreasing = 1
    while heap:
        if not i or heap[0] <= heap[1]:
            non_decreasing += 1
            heappush(heap, heappop(heap) + 1)
    return non_decreasing

def process_queries(arr: List[int], queries: List[List[int]]) -> List[int]:
    results = []
    sorted_arr = sorted(arr)
    sorted_stack: List[int] = []
    for i in range(len(arr) - 1, -1, -1):
        if len(sorted_stack) <= i:
            sorted_stack.append(arr[i])
        else:
            if sorted_stack[-1] > arr[i]:
                sorted_stack[-1] = arr[i]

    i = 0
    for query in queries:
        if query[0] == 1:
            index, value = query
            arr[index-1] = value
        elif query[0] == 2:
            l, r = query
            start = max(l-1 if l != 1 else None, 0)
            l = arr[start] if l != 1 else None
            limit = min(r-1 if r != len(arr) else None, len(arr))
            limit = arr[limit]
            current = None
            if start != limit:
                heapq.heapify(sorted_stack)
                current = min(l, sorted_stack[0]) if start < limit else sorted_stack[0]
            results.append(-1 if current is None else current + 1)
            # Heapify will ensure we always have non-decreasing values after changing arr[l-1]
            if l == limit:
                sorted_stack.extend(arr[l+1:limit+1])
            arr[l-1] = current
    return results

