def rotate_tile(grid, x, y):
    """Rotate the tile at coordinates (x, y) in the grid 90 degrees clockwise."""
    tile = grid[y][x]
    top = grid[y-1][x] if 0 <= y-1 < len(grid) else ''
    right = grid[y][x+1] if x+1 < len(grid[0]) else ''
    bottom = grid[y+1][x] if y+1 < len(grid) else ''
    left = grid[y][x-1] if 0 <= x-1 < len(grid[0]) else ''
    grid[y][x] = bottom + left
    grid[y-1][x] = right + tile
    grid[y][x+1] = top
    grid[y+1][x] = bottom

def process(tile_pattern):
