            elif grid[i][j] == 'D':
                if stack and stack[0][0] == i:
                    move = (i, j, stack[0][1] - stack[0][0], i)
                    operations.append((i, j, *move))
                    stack[0] = stack[0][:1] + (-stack[0][1] - stack[0][0],) + stack[0][1:]
                stack.pop()
                grid[i][j] = 'D'
            elif grid[i][j] == 'L':
                if stack and stack[-1][0] == i:
                    move = (i, j, *stack[-1][1:] + (-stack[-1][0] - stack[-1][1],))
                    operations.append((i, j, *move))
                stack.append((i, j))
                grid[i][j] = 'L'
            elif grid[i][j] == 'R':
                if stack and stack[-1][1] == j:
                    move = (stack[-1][0] + stack[-1][1] + 1, j)
