from collections import deque

def canPop(stack, num):
    idx = deque(stack).index(num) if num in stack else None
    if idx == -1: 
        return False
    if idx != 0 and stack[-2] == num:
        return False
    return True

def isDefinable(stack, nums):
    i = 0
    l = len(nums)
    while i < l:
        if not canPop(stack, nums[i]):
            stack.popleft()
        else:
            stack.append(nums[i])
            i += 1
        if len(stack) == 0:
            break
    return not stack

def countDefinableSubarrays(nums):
    l = len(nums)
    idx = -1
    count = 0
    for i in range(l):
        while idx >= 0 and (nums[idx] > nums[i] or i == 0):
            idx = findDrop(nums[idx+1:])        
        count += len(nums[idx+1:])
        if i == l-1 or idx == -1:
            break
        findLow(nums, idx)
    return count

def findLow(dp, low):
