from collections import deque

def is_stack_exterminable(elements):
    stack = deque()
    for element in elements:
        if stack and (stack[0] != element or stack[-1] != element):
            stack.appendleft(element)
        else:
            stack.pop()
        if len(stack) == 0:
            return True
    return False

def solve(query):
    elements = deque([int(i) for i in query.split()])
    q, _, s, n = int(elements.popleft()), elements.popleft()
    stack_exterminable_count = 0
    s_index = 1

    for index in range(q // s):
        if s * index < n:
            stack_index = s * index + 1
            stack_limit = s * index + s
            elements.popleft()  # Skip the element
        else:
            stack_index = n - index - 1
            stack_limit = n

        if stack_index > stack_limit:
            break

        # Remove elements from elements
        elements[mapped[stack_index]:stack_limit] = []

        for block_start in range(stack_index, stack_limit):
            if is_stack_exterminable(elements[mapped[block_start]:stack_limit]):
                stack_exterminable_count += 1
            elif block_start > 0 and block_start % s == 0:
                break
            else:
                break

    return stack_exterminable_count

# Assume mapped_lookup is a dictionary mapping numbers to their unique indices.
for _ in range(int(input())):
    n = int(input())
    elements = input().strip()
    print(solve(elements))
