def max_queried_towers(n, towers, quests, actions):
    towers_active_times = [0] * n
    query_towers = set()

    for i in range(n):
        if towers[i] in quests:
            query_towers.add(i)
            towers_active_times[i] = quests[towers[i]][1]

    for action in actions:
        for tower_id in query_towers:
            if towers[tower_id] == action[0] and towers_active_times[tower_id] <= action[1]:
                return max(query_towers)

        # During the t turn, all towers are considered.
        for action in actions:
            for tower_id in range(n):
                if towers[tower_id] == action[0] and actions[action[1] - action[0]][0] == towers[tower_id]:
                    query_towers.add(tower_id)

    return max(query_towers)

# Example usage:
