    tree_nodes = {}
    for u, v in edges:
        if u not in tree_nodes:
            tree_nodes[u] = TreeNode(u)
        if v not in tree_nodes:
            tree_nodes[v] = TreeNode(v)
        tree_nodes[u].children.append(tree_nodes[v])
