from collections import Counter

def get_characters(s):
    return Counter(s)

def apply_operations(s):
    c = Counter(s)
    replaced = []
    for i in range(len(s) - 1):
        left = s[i]
        right = s[i + 1]
        if c[left] > 0 and c[right] > 0:
            c[left] -= 1
            c[right] -= 1
            replaced.append(left)
            replaced.append(right)
        else:
            if c[left] > 0:
                c[left] -= 1
            if c[right] > 0:
                c[right] -= 1
    if replaced:
        return ''.join(replaced)
    else:
        return s

def is_balanced(c):
    return 0 <= c['a'] - c['b'] <= 1 and 0 <= c['a'] - c['c'] <= 1 and 0 <= c['b'] - c['c'] <= 1

s_length, s = map(int, input().split()), input().strip()
characters = Counter(s)
balanced_count = 0

# Count the number of possible balanced strings
for i in range(s_length + 1):
    new_characters = Counter(characters)
    for _ in range(i):
        new_characters = apply_operations(''.join(new_characters.elements()))  # Apply operations to replace adjacent characters
        if is_balanced(new_characters):
            balanced_count += 1
        new_characters = new_characters.elements()
    characters = new_characters

# Output the result modulo 51123987
