from collections import defaultdict

def count_afraid_monsters(stones, monsters, max_dist):
    monster_to_positions = defaultdict(list)
    for i, monster in enumerate(monsters):
        monster_to_positions[monster[0] - monster[1]].append(i)

    afraid_count = 0
    for i, (stone_x, stone_y) in enumerate(stones):
        for pos in monster_to_positions[abs(stone_x - 0) + abs(stone_y - 0) - max_dist]:
            if monster_to_positions[pos & ~(pos+1)] and all(abs(mx) + abs(my) <= max_dist for mxi, myi in monsters[pos:mxi+1]):
                afraid_count += 1
    return afraid_count
